import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import 'auth_providers.dart';import 'register_screen.dart';import 'forgot_password_screen.dart';class LoginScreen extends ConsumerStatefulWidget{const LoginScreen({super.key});@override ConsumerState<LoginScreen>createState()=>_LoginState();}class _LoginState extends ConsumerState<LoginScreen>{final phone=TextEditingController(),password=TextEditingController();String? error;@override Widget build(BuildContext c)=>Scaffold(body:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Text('BLACK HORSE',style:TextStyle(fontSize:28)),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error!=null)Text(error!),FilledButton(onPressed:()async{if(phone.text.isEmpty||password.text.isEmpty){setState(()=>error='Phone and password are required');return;}try{await ref.read(authSessionProvider.notifier).login(phone.text,password.text);if(c.mounted)c.go('/home');}catch(e){setState(()=>error=e.toString());}},child:const Text('Login')),TextButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ForgotPasswordScreen())),child:const Text('Forgot password')),TextButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const RegisterScreen())),child:const Text('Create account'))])));}
